/// <reference types="vite/client" />

// Explicit asset declarations for TypeScript projects that restrict tsconfig types.
declare module '*.png' {
  const src: string
  export default src
}

declare module '*.jpg' {
  const src: string
  export default src
}

declare module '*.jpeg' {
  const src: string
  export default src
}

declare module '*.svg' {
  const src: string
  export default src
}
